css:
.referral-letter {
	font-family: Helvetica, Arial, sans-serif;
	color: #16233a;
	font-size: 10.5pt;
	line-height: 1.5;
}
.letter-header {
	display: flex;
	justify-content: space-between;
	align-items: baseline;
	border-bottom: 0.5mm solid #1f3b73;
	padding-bottom: 3mm;
	margin-bottom: 4mm;
}
.letter-brand { font-size: 15pt; font-weight: bold; color: #1f3b73; }
.letter-issuer { font-size: 9pt; color: #5a6a85; }
.letter-meta {
	display: flex;
	justify-content: space-between;
	font-size: 9pt;
	color: #5a6a85;
	margin-bottom: 5mm;
}
.priority { font-weight: bold; text-transform: uppercase; letter-spacing: 0.3mm; }
.priority-high { color: #a33; }
.priority-medium { color: #a67c00; }
.priority-low { color: #2a6b3a; }
.letter-to { margin-bottom: 5mm; }
.field-label { font-size: 7.5pt; text-transform: uppercase; letter-spacing: 0.3mm; color: #5a6a85; }
.letter-to-name { font-size: 12pt; font-weight: bold; }
.letter-to-attn { font-size: 9.5pt; color: #16233a; margin-top: 1mm; }
.letter-body p { margin: 2mm 0; }
.patient-table { width: 100%; border-collapse: collapse; margin: 3mm 0 5mm; }
.patient-table td { padding: 1.2mm 0; vertical-align: top; }
.patient-table td.field-label { width: 32mm; }
.reason-text { white-space: pre-wrap; }
.letter-signature { margin-top: 10mm; }
.letter-org { font-size: 9pt; color: #5a6a85; }
.letter-footer { margin-top: 8mm; font-size: 8pt; color: #5a6a85; border-top: 0.3mm solid #d5dae3; padding-top: 3mm; }

html:
{%- set patient = frappe.db.get_value("Patient", doc.patient, ["patient_name", "sex", "custom_bandhu_id", "mobile"], as_dict=True) or {} -%}
{%- set encounter = frappe.db.get_value("Patient Encounter", doc.patient_encounter, ["encounter_date"], as_dict=True) if doc.patient_encounter else {} -%}
{%- set session = frappe.db.get_value("Bandhu Clinic Session", doc.clinic_session, ["site"], as_dict=True) if doc.clinic_session else {} -%}
{%- set site_name = frappe.db.get_value("Site", session.site, "site_name") if session and session.site else "" -%}
{%- set referring_doctor = frappe.db.get_value("Healthcare Practitioner", doc.referral_by_source, "practitioner_name") if doc.referral_by_source else "" -%}
{%- set referred_practitioner = frappe.db.get_value("Healthcare Practitioner", doc.referred_to_practitioner, "practitioner_name") if doc.referred_to_practitioner else "" -%}
{%- set clinic_id = patient.custom_bandhu_id or "" -%}
{%- if clinic_id|length == 10 -%}
	{%- set grouped_clinic_id = clinic_id[:2] ~ " " ~ clinic_id[2] ~ " " ~ clinic_id[3:5] ~ " " ~ clinic_id[5:] -%}
{%- else -%}
	{%- set grouped_clinic_id = clinic_id -%}
{%- endif -%}
<div class="referral-letter">
	<div class="letter-header">
		<div class="letter-brand">Bandhu Mobile Clinics</div>
		<div class="letter-issuer">CMID &middot; National Health Mission PPP</div>
	</div>

	<div class="letter-meta">
		<span>{{ _("Referral") }}: {{ doc.name | e }}</span>
		<span>{{ _("Date") }}: {{ frappe.utils.format_datetime(doc.created_on, "d MMM yyyy") if doc.created_on else "" }}</span>
		{%- if doc.priority %}<span class="priority priority-{{ doc.priority | lower | e }}">{{ _(doc.priority) }} {{ _("Priority") }}</span>{% endif -%}
	</div>

	<div class="letter-to">
		<div class="field-label">{{ _("To") }}</div>
		<div class="letter-to-name">{{ (doc.referred_to or "") | e }}</div>
		{%- if referred_practitioner %}
		<div class="letter-to-attn">{{ _("Attn") }}: {{ referred_practitioner | e }}</div>
		{%- endif %}
	</div>

	<div class="letter-body">
		<p>{{ _("This is to refer the following patient, seen at a Bandhu Mobile Clinic camp, for further evaluation and management.") }}</p>

		<table class="patient-table">
			<tr><td class="field-label">{{ _("Patient") }}</td><td>{{ (patient.patient_name or "") | e }}</td></tr>
			<tr><td class="field-label">{{ _("Age / Sex") }}</td><td>{{ (doc.age or "") | e }}{% if doc.age and patient.sex %} / {% endif %}{% if patient.sex %}{{ _(patient.sex) }}{% endif %}</td></tr>
			<tr><td class="field-label">{{ _("Clinic ID") }}</td><td>{{ grouped_clinic_id | e }}</td></tr>
			{%- if patient.mobile %}
			<tr><td class="field-label">{{ _("Mobile") }}</td><td>{{ patient.mobile | e }}</td></tr>
			{%- endif %}
			<tr><td class="field-label">{{ _("Seen at") }}</td><td>{{ (site_name or "") | e }}{% if encounter and encounter.encounter_date %} &middot; {{ frappe.utils.formatdate(encounter.encounter_date) }}{% endif %}</td></tr>
		</table>

		<div class="field-label">{{ _("Reason for Referral") }}</div>
		<p class="reason-text">{{ (doc.reason or "") | e }}</p>

		{%- if doc.notes %}
		<div class="field-label">{{ _("Additional Notes") }}</div>
		<p class="reason-text">{{ doc.notes | e }}</p>
		{%- endif %}
	</div>

	<div class="letter-signature">
		<div>{{ _("Referring Doctor") }}: {{ (referring_doctor or "") | e }}</div>
		<div class="letter-org">{{ _("Bandhu Mobile Clinics, CMID") }}</div>
	</div>

	<div class="letter-footer">{{ _("For follow-up, contact the Bandhu Helpline quoting the referral number above.") }}</div>
</div>
